import{_ as a,o as t,c as n,ah as s}from"./chunks/framework.Sdx4l2LO.js";const u=JSON.parse('{"title":"ADR-019: Local Mod Manager Client (M12)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-019-mod-manager-client.md","filePath":"adr/ADR-019-mod-manager-client.md","lastUpdated":1774839561000}'),i={name:"adr/ADR-019-mod-manager-client.md"};function o(l,e,r,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="adr-019-local-mod-manager-client-m12" tabindex="-1">ADR-019: Local Mod Manager Client (M12) <a class="header-anchor" href="#adr-019-local-mod-manager-client-m12" aria-label="Permalink to &quot;ADR-019: Local Mod Manager Client (M12)&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-03-29<br><strong>Supersedes:</strong> N/A<br><strong>Related:</strong> ADR-011 (Desktop Companion App)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>DINOForge currently lacks a local mod management interface within the Desktop Companion application. Users need a way to:</p><ol><li><strong>Browse</strong> available mods from local folders or remote HTTP catalog endpoints</li><li><strong>Check for updates</strong> by comparing installed pack versions against catalog versions</li><li><strong>Detect conflicts</strong> between active packs, including missing dependencies and incompatible versions</li></ol><p>The Desktop Companion (WinUI 3 app) already provides Dashboard, Pack List, Debug Panel, and Settings views. Extending it with mod management features provides a unified, familiar experience without introducing a separate application.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We will extend the Desktop Companion application with three new pages and supporting services:</p><h3 id="new-views" tabindex="-1">New Views <a class="header-anchor" href="#new-views" aria-label="Permalink to &quot;New Views&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Page</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Browse</strong></td><td>Display available packs from a catalog (local folder or HTTP URL), with search and type filtering</td></tr><tr><td><strong>Updates</strong></td><td>Compare installed versions against catalog versions, show available updates</td></tr><tr><td><strong>Conflicts</strong></td><td>Run dependency resolution, display conflicts, missing dependencies, and computed load order</td></tr></tbody></table><h3 id="new-services" tabindex="-1">New Services <a class="header-anchor" href="#new-services" aria-label="Permalink to &quot;New Services&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Service</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>IModCatalogService</code> / <code>ModCatalogService</code></td><td>Load pack metadata from file:// or https:// catalog sources</td></tr><tr><td><code>UpdateCheckService</code></td><td>Semantic version comparison between installed and catalog packs</td></tr><tr><td><code>ConflictDetectionService</code></td><td>Use SDK&#39;s <code>PackDependencyResolver</code> to detect conflicts and compute load order</td></tr></tbody></table><h3 id="new-viewmodels" tabindex="-1">New ViewModels <a class="header-anchor" href="#new-viewmodels" aria-label="Permalink to &quot;New ViewModels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ViewModel</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>BrowseViewModel</code></td><td>Catalog loading, search/filter, install action</td></tr><tr><td><code>UpdateViewModel</code></td><td>Update detection and download launch</td></tr><tr><td><code>ConflictViewModel</code></td><td>Conflict analysis, dependency tree visualization</td></tr></tbody></table><h3 id="architecture-flow" tabindex="-1">Architecture Flow <a class="header-anchor" href="#architecture-flow" aria-label="Permalink to &quot;Architecture Flow&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐     ┌─────────────────┐     ┌─────────────────┐</span></span>
<span class="line"><span>│  Catalog Source │────▶│  ModCatalogSvc  │────▶│  BrowseViewModel│</span></span>
<span class="line"><span>│  (file:// or    │     │  (IModCatalog)  │     │                 │</span></span>
<span class="line"><span>│   https://)     │     └─────────────────┘     └────────┬────────┘</span></span>
<span class="line"><span>└─────────────────┘                                       │</span></span>
<span class="line"><span>                                                          ▼</span></span>
<span class="line"><span>┌─────────────────┐     ┌─────────────────┐     ┌─────────────────┐</span></span>
<span class="line"><span>│  Installed Packs│────▶│ UpdateCheckSvc  │────▶│  UpdateViewModel│</span></span>
<span class="line"><span>│  (PackViewModel)│     │                 │     │                 │</span></span>
<span class="line"><span>└─────────────────┘     └─────────────────┘     └────────┬────────┘</span></span>
<span class="line"><span>                                                          │</span></span>
<span class="line"><span>┌─────────────────┐     ┌─────────────────┐              │</span></span>
<span class="line"><span>│  PackDependency │◀────│ConflictDetection│◀─────────────┘</span></span>
<span class="line"><span>│  Resolver (SDK) │     │  Service        │</span></span>
<span class="line"><span>└────────┬────────┘     └────────┬────────┘</span></span>
<span class="line"><span>         │                       │</span></span>
<span class="line"><span>         ▼                       ▼</span></span>
<span class="line"><span>┌─────────────────┐     ┌─────────────────┐</span></span>
<span class="line"><span>│  Load Order    │     │  ConflictReport │</span></span>
<span class="line"><span>│  (DependencyRes)│     │  - Conflicts    │</span></span>
<span class="line"><span>└─────────────────┘     │  - MissingDeps  │</span></span>
<span class="line"><span>                       │  - LoadOrderErrs │</span></span>
<span class="line"><span>                       └─────────────────┘</span></span></code></pre></div><h2 id="user-stories" tabindex="-1">User Stories <a class="header-anchor" href="#user-stories" aria-label="Permalink to &quot;User Stories&quot;">​</a></h2><h3 id="browse-packs" tabindex="-1">Browse Packs <a class="header-anchor" href="#browse-packs" aria-label="Permalink to &quot;Browse Packs&quot;">​</a></h3><ul><li><strong>Given</strong> a catalog URL or folder path</li><li><strong>When</strong> user enters the source and clicks Load</li><li><strong>Then</strong> the application displays all packs with name, author, version, type, and description</li><li><strong>And</strong> installed packs are marked with an &quot;Installed&quot; badge</li></ul><h3 id="search-and-filter" tabindex="-1">Search and Filter <a class="header-anchor" href="#search-and-filter" aria-label="Permalink to &quot;Search and Filter&quot;">​</a></h3><ul><li><strong>Given</strong> a loaded catalog</li><li><strong>When</strong> user types in the search box or selects a type filter</li><li><strong>Then</strong> the list updates to show only matching packs</li></ul><h3 id="check-for-updates" tabindex="-1">Check for Updates <a class="header-anchor" href="#check-for-updates" aria-label="Permalink to &quot;Check for Updates&quot;">​</a></h3><ul><li><strong>Given</strong> installed packs and a catalog with newer versions</li><li><strong>When</strong> user clicks &quot;Check for Updates&quot;</li><li><strong>Then</strong> the application shows which packs have updates available</li><li><strong>And</strong> displays current → available version</li></ul><h3 id="detect-conflicts" tabindex="-1">Detect Conflicts <a class="header-anchor" href="#detect-conflicts" aria-label="Permalink to &quot;Detect Conflicts&quot;">​</a></h3><ul><li><strong>Given</strong> multiple active packs with dependencies and conflicts</li><li><strong>When</strong> user navigates to the Conflicts page and clicks Analyze</li><li><strong>Then</strong> the application shows: <ul><li>Packs declaring conflicts with other active packs</li><li>Packs with missing dependencies</li><li>The computed load order</li></ul></li></ul><h3 id="dependency-tree" tabindex="-1">Dependency Tree <a class="header-anchor" href="#dependency-tree" aria-label="Permalink to &quot;Dependency Tree&quot;">​</a></h3><ul><li><strong>Given</strong> loaded packs</li><li><strong>When</strong> user selects a pack from the load order list</li><li><strong>Then</strong> the dependency tree for that pack is displayed</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li>Unified experience within Desktop Companion</li><li>Clear visibility into pack conflicts before game launch</li><li>Support for both local and remote catalog sources</li><li>Semantic version comparison for accurate update detection</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li>Increases Desktop Companion complexity</li><li>Requires users to configure catalog sources</li></ul><h3 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h3><ul><li>Remote catalog endpoints may be unavailable or slow</li><li>Complex dependency graphs may produce large load order lists</li></ul><h2 id="implementation-notes" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation Notes&quot;">​</a></h2><h3 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h3><ul><li>All services use <code>ILogger&lt;T&gt;</code> for diagnostic logging</li><li>Services are registered in <code>App.xaml.cs</code> DI container</li><li>ViewModels use <code>ObservableObject</code> + <code>RelayCommand</code> pattern (CommunityToolkit.Mvvm)</li></ul><h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><ul><li>All XAML views use existing DINOForge theme styles</li><li>Views get their ViewModels from DI via <code>App.Services.GetRequiredService&lt;T&gt;()</code></li><li>Code-behind handles navigation events only</li></ul><h3 id="sdk-integration" tabindex="-1">SDK Integration <a class="header-anchor" href="#sdk-integration" aria-label="Permalink to &quot;SDK Integration&quot;">​</a></h3><ul><li><code>ConflictDetectionService</code> wraps <code>PackDependencyResolver</code> from <code>DINOForge.SDK.Dependencies</code></li><li>Provides higher-level UI-focused reporting on top of SDK primitives</li></ul>`,41)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
